const startedAt = Date.now();
const input = $json ?? {};
const body = input.body ?? {};
const query = input.query ?? {};
const headers = input.headers ?? {};

function readHeader(name) {
  const target = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (String(key).toLowerCase() === target) return Array.isArray(value) ? value[0] : value;
  }
  return null;
}

function env(name, fallback = null) {
  try {
    return $env[name] || fallback;
  } catch (e) {
    return fallback;
  }
}

function result(httpStatus, status, message, extra = {}) {
  const failureStatuses = ['UNAUTHORIZED', 'CONFIG_ERROR', 'SALESFORCE_AUTH_ERROR', 'SALESFORCE_REQUEST_ERROR', 'INVALID_RESPONSE', 'INVALID_REQUEST', 'INTERNAL_ERROR'];
  return [{ json: {
    success: httpStatus >= 200 && httpStatus < 300 && !failureStatuses.includes(status),
    http_status: httpStatus,
    status,
    message: message ?? null,
    duration_ms: Date.now() - startedAt,
    ...extra
  }}];
}

const expectedToken = env('RENOV_INTERNAL_TOKEN');
if (!expectedToken) {
  return result(500, 'CONFIG_ERROR', 'RENOV_INTERNAL_TOKEN no esta configurado en n8n.');
}

const auth = String(readHeader('authorization') ?? '');
const bearer = auth.match(/^Bearer\s+(.+)$/i)?.[1] ?? null;
const providedToken = readHeader('x-internal-token') ?? bearer;
if (providedToken !== expectedToken) {
  return result(401, 'UNAUTHORIZED', 'Token interno invalido.');
}

const phone = String(body.phone ?? query.phone ?? '').trim();
const accountId = String(body.accountId ?? query.accountId ?? '').trim();
if (!phone && !accountId) {
  return result(400, 'INVALID_REQUEST', 'Debe enviar phone o accountId.');
}
if (phone && !/^\+[1-9][0-9]{7,14}$/.test(phone)) {
  return result(400, 'INVALID_REQUEST', 'phone debe estar en formato E.164.');
}

const salesforceBaseUrl = env('SALESFORCE_DEV_BASE_URL', 'https://quicklink--uat.sandbox.my.salesforce.com').replace(/\/+$/, '');
const tokenUrl = env('SALESFORCE_DEV_TOKEN_URL', `${salesforceBaseUrl}/services/oauth2/token`);
const clientId = env('SALESFORCE_DEV_CLIENT_ID');
const clientSecret = env('SALESFORCE_DEV_CLIENT_SECRET');
if (!clientId || !clientSecret) {
  return result(500, 'CONFIG_ERROR', 'Credenciales Salesforce DEV no configuradas.');
}

try {
  const tokenResponse = await fetch(tokenUrl, {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'client_credentials',
      client_id: clientId,
      client_secret: clientSecret
    })
  });
  const tokenText = await tokenResponse.text();
  let tokenBody = {};
  try { tokenBody = tokenText ? JSON.parse(tokenText) : {}; } catch (e) { tokenBody = {}; }
  if (!tokenResponse.ok || !tokenBody.access_token) {
    return result(502, 'SALESFORCE_AUTH_ERROR', 'No se pudo obtener token Salesforce DEV.', { salesforce_http_status: tokenResponse.status });
  }

  const routingUrl = new URL(`${salesforceBaseUrl}/services/apexrest/quicklink/v1/routing/resolve`);
  if (phone) routingUrl.searchParams.set('phone', phone);
  if (accountId) routingUrl.searchParams.set('accountId', accountId);

  const routingResponse = await fetch(routingUrl, {
    method: 'GET',
    headers: {
      authorization: `Bearer ${tokenBody.access_token}`,
      accept: 'application/json'
    }
  });
  const routingText = await routingResponse.text();
  let routingBody = {};
  try { routingBody = routingText ? JSON.parse(routingText) : {}; } catch (e) {
    return result(502, 'INVALID_RESPONSE', 'Salesforce devolvio una respuesta no JSON.', { salesforce_http_status: routingResponse.status });
  }

  const allowedStatuses = ['MATCHED', 'MULTI_MATCH', 'NOT_FOUND', 'INVALID_REQUEST', 'INTERNAL_ERROR'];
  const businessStatus = String(routingBody.status ?? 'INVALID_RESPONSE');
  if (!allowedStatuses.includes(businessStatus)) {
    return result(502, 'INVALID_RESPONSE', 'Salesforce devolvio status no reconocido.', { salesforce_http_status: routingResponse.status, raw_status: businessStatus });
  }

  const routingAction = {
    MATCHED: 'matched',
    MULTI_MATCH: 'escalate_multi_match',
    NOT_FOUND: 'not_found',
    INVALID_REQUEST: 'invalid_request',
    INTERNAL_ERROR: 'escalate_internal_error'
  }[businessStatus];

  return result(routingResponse.status, businessStatus, routingBody.message ?? null, {
    salesforce_http_status: routingResponse.status,
    routing_action: routingAction,
    phone: routingBody.phone ?? phone ?? null,
    accountId: routingBody.accountId ?? accountId ?? null,
    accountName: routingBody.accountName ?? null,
    accountActive: routingBody.accountActive ?? null,
    ownerId: routingBody.ownerId ?? null,
    ownerName: routingBody.ownerName ?? null,
    vehicleId: routingBody.vehicleId ?? null,
    vehiclePlate: routingBody.vehiclePlate ?? null,
    contractId: routingBody.contractId ?? null,
    contractNumber: routingBody.contractNumber ?? null,
    contractStatus: routingBody.contractStatus ?? null,
    contractEndDate: routingBody.contractEndDate ?? null,
    resolvedBy: routingBody.resolvedBy ?? null,
    candidateAccountIds: routingBody.candidateAccountIds ?? null,
    escalate: routingBody.escalate ?? (businessStatus === 'MULTI_MATCH' || businessStatus === 'INTERNAL_ERROR')
  });
} catch (error) {
  return result(502, 'SALESFORCE_REQUEST_ERROR', 'Fallo consultando Salesforce routing resolve.', { error_message: String(error?.message ?? error) });
}
